/**
 * Stable server-side identifiers for persisted artifacts (ADR-008):
 * assistant message IDs and stream IDs are generated by this module, never
 * trusted from the client.
 */
import { createIdGenerator } from 'ai';

/** Server-generated assistant message IDs, persisted with the message. */
export const createMessageId: () => string = createIdGenerator({ prefix: 'msg', size: 24 });

/** Server-generated stream IDs for resumable-stream checkpoints. */
export const createStreamId: () => string = createIdGenerator({ prefix: 'strm', size: 24 });
